# -*- coding: UTF-8 -*-"""===============================================@Author ：kidding@Date   ：2024/6/3 22:26@File   ：Class@IDE    ：PyCharm==================================================""""""====================================类===============================class 类名称:    类的属性(成员变量)    类的行为(成员方法)    # 基于类创建对象    对象名 = 类名称()# 调用    对象名.成员变量    对象名.成员方法()    # 函数,形参可以为0-N个   ======>  类外函数定义的方式    def 函数名(形参1,形参2,..,形参N):        函数体        # 方法,形参可以为0-N个   =======> 在一个类中定义函数，叫做方法，与普通定义函数有一点点差别，就是 self关键字，self关键字必须填写    def 方法名(self,形参1,形参2,..,形参N):        方法体"""class Student:    name = None    sex = None    age = None    # 构造方法：通过传参的形式快速对属性赋值    # 在类可以使用：__init__() ，方法，即构造方法, 快速为对象赋值    def __init__(self, name, sex, age):        """        (1)在创建类对象（构造类）的时候，会自动执行，将传入参数自动传递给__init__方法使用。        (2)构造方法也是成员方法，定义时也需要在参数列表中提供：self        (3)变量定义在构造方法内部，如果要成为成员变量，需要用self来表示，例如self.name        (4)使用了构造方法，创建对象时必须传参否则会报错        :param name: 姓名        :param sex: 性别        :param age: 年龄        """        self.name = name        self.sex = sex        self.age = age    # 自定义打印输出内容    def __str__(self):        return f"Student对象,name={self.name},age={self.age}"    # 定义比较函数，相当于重载比较运算符    def __lt__(self, other):        return self.age < other.age    # self关键字在成员方法定义的时候必须填写，表示类对象自身    # 在方法内部，想要访问类的成员变量，必须使用self    def say_hi1(self):        print(f"大家好，我叫{self.name}")    def say_hi2(self):        print(f"大家好，我叫{name}")    def say_hi3(self, msg):        print(f"大家好，我是{msg}")# 实例化对象stu1 = Student("张三", "男", 9999)stu1.say_hi1()       # 调用say_hi1时不报错# stu1.say_hi2()     # 调用say_hi2时报错，'name' is not defined# 当我们使用对象调用方法的时，self会自动被python传入,尽管在参数列表中，但是传参的时候可以忽略它。stu1.say_hi3("练习两年半的偶像实习生")# 构造方法：通过传参的形式快速对属性赋值# 创建对象并赋值stu2 = Student("李四", "男", 1111)"""-------------------------------------------------------------------------------    方法	                                            功能  __init__	                        构造方法，可用于创建类对象的时候设置初始化行为  __str__	                        字符串方法，用于实现类对象转字符串的行为  __lt__	                        用于2个类对象进行小于(<)或大于(>)比较  __le__	                        用于2个类对象进行小于等于(<=)或大于等于(>=)比较  __eq__	                        用于2个类对象进行相等(==)比较-------------------------------------------------------------------------------"""stu1.__str__()print(stu1)stu3 = Student("李白", '男', 1000)stu4 = Student("罗辑", '女', 300)print(stu4 > stu3) # 报错"""封装：    私有成员/方法： 在类中提供仅供内部使用的属性和方法，无法被对象调用        基本语法：            私有成员变量：变量名以__开头（2个下划线）            私有成员方法：方法名以__开头（2个下划线)            继承:    一个类继承另外一个类的所有成员变量和成员方法(不含私有)    多态：    多种状态，即完成某个行为时，使用不同的对象会得到不同的状态    多态常作用在继承关系上，函数(方法)形参声明接收父类对象，实际传入父类的子类对象进行工作，即： 以父类做定义声明，以子类做实际工作，用以获得同一行为, 不同状态        （1）抽象类(接口)：包含抽象方法的类，子类必须实现抽象方法    （2）抽象方法：没有具体实现的方法（只含pass）称之为抽象方法        pass是位语句，用来保证函数（方法）或类定义的完整性，表示无内容，空的意思"""class People:    name = None  # 普通成员变量    __age = 16  # 私有成员变量    # 普通成员方法    def show(self):        self.__check()      # 在类中使用私有成员变量        if self.__age > 18: # 在类中使用私有成员变量            print("成年人")        else:            print("未成年")    # 私有成员方法    def __check(self):        print("自检")p1 = People()p1.show()# p1.__check() # 报错，不能调用私有成员方法# 继承# 父类class Phone:    producer = "apple"  # 厂商    def call_by_4g(self):        print("4g通话")# 子类继承Phoneclass Phone2022(Phone):    face_id = True  # 面部识别    def call_by_5g(self):        print("2022最新5G通话")# 创建对象phone = Phone2022()# 使用print(phone.producer) # 可调用 继承自Phone的成员变量print(phone.face_id) # 可调用 自身的成员变量phone.call_by_4g() # 可调用 继承自Phone的成员方法phone.call_by_5g() # 可调用 自身的成员方法# 多继承class Phone:    producer = "huawei"  # 厂商class Camera:    producer = "suoni"  # 厂商class Phone2022(Phone, Camera):    face_id = True  # 面部识别    def call_by_5g(self):        print("2022最新5G通话")phone = Phone2022()print(phone.producer)  # 打印结果为apple而非suoniprint("="*60)class Computer:    cpu=None    memory=None    disk=None    def __init__(self,cpu,memory,disk):        self.cpu=cpu        self.memory=memory        self.disk=disk    def get_details(self):        return "cpu:{}\t内存:{}\t硬盘：{}\t".format(self.cpu,self.memory,self.disk)class PC(Computer):    brand = None    def __init__(self, cpu, memory, disk, brand):        # 用super().父类成员/方法调用父类的代码        super().__init__(cpu,memory,disk)        self.brand=brand    def print_info(self):        print("品牌：{}\t{}".format(self.brand, self.get_details()))pc=PC("intel", 32,1000,"dell")pc.print_info()print("="*60)class A01:    def compare_list(self,list01):        return max(list01)a01=A01()print(a01.compare_list([1.2, 3.4, 5.6 ,7.8]))class BOOK:    name =None    price=None    def __init__(self,name,price):        self.name = name        self.price = price    def update_price(self):        if  self.price > 150:            self.price=150        elif  self.price > 100:            self.price=100    def book_info(self):        print("书名：{}，价格：{}".format(self.name,self.price))a02=BOOK("haliluya",148)a02.update_price()a02.book_info()import mathclass Circle:    radius = None    def __init__(self, radius):        self.radius=radius    def len_circle(self):        print("圆周长为：{}".format(2*math.pi * self.radius))    def area_circle (self):        print("圆面积为：{}".format(math.pi * self.radius * self.radius))a03=Circle(6)a03.len_circle()a03.area_circle()print("="*60)class Employee:    __name = None    __salary = None    def __init__(self, name, salary):        self.__name=name        self.__salary=salary    def set_name(self, name):        self.__name=name    def set_salary(self, salary):        self.__salary=salary    def get_name(self):       return  self.__name    def get_annual(self):        return self.__salary * 12class Worker(Employee):    def work(self):        print("员工 {}正在工作……".format(self.get_name()))    def get_annual(self):        return super().get_annual()class Manager(Employee):    __bonus=None    def __init__(self, name, salary, bonus):        super().__init__(name, salary)        self.__bonus=bonus    def manage(self):        print("经理 {} 正在管理工作……".format(self.get_name()))    def get_annual(self):        return super().get_annual() + self.__bonusdef working(e:Employee):    if isinstance(e, Worker):        e.work()    elif isinstance(e,Manager):        e.manage()    else:        print("无法确定工作状态")def show_employee_annual(e:Employee):    print("{}年工资是{}".format(e.get_name(), e.get_annual()))worker = Worker("tim", 10000)show_employee_annual(worker)working(worker)manager = Manager("bob", 20000, 999999)show_employee_annual(manager)working(manager)